import{S as e,o as n,c as t,a9 as l,B as p}from"./chunks/framework.DxG24V0C.js";const o="/agentsrc/images/codex/04-double-defenses.svg",h="/agentsrc/images/codex/04-hybrid-history.svg",E=JSON.parse('{"title":"Codex 压缩机制：为什么核心压缩路径要依赖 LLM？","description":"","frontmatter":{"title":"Codex 压缩机制：为什么核心压缩路径要依赖 LLM？"},"headers":[],"relativePath":"codex/04-compact.md","filePath":"codex/04-compact.md","lastUpdated":1788847143000}'),r={name:"codex/04-compact.md"},g=Object.assign(r,{setup(k){const i=[{question:"为什么简单的 FIFO（先进先出）截断策略不适合作为 Agent 上下文压缩的首选手段？",options:["因为 FIFO 截断会导致 Rust 编译器的字符串生命周期检查失败，引发内存泄漏","因为 FIFO 截断会直接丢弃最老的对话，导致模型丢失早期的关键需求和架构决策","因为 FIFO 截断无法处理多模态数据，遇到图片或二进制文件时会直接崩溃","因为 FIFO 截断会破坏大模型的前缀缓存机制，导致 API 调用成本大幅飙升"],correct:1,explanation:"如果直接丢弃最老的对话，模型会丢失早期的关键上下文（如用户的初始需求、早期的架构决策）。一旦这些信息丢失，模型的后续推理就会缺乏支撑，因此需要语义摘要。"},{question:"在 run_turn 流程中，Mid-turn 的 run_auto_compact 触发条件是什么？",options:["当单轮生成结束后，只要系统发现模型吐出了超过 1000 个 Token 的内容就会立刻触发","当系统检测到 token_limit_reached 并且 needs_follow_up（模型还要继续工具或有待处理输入）时触发","当模型连续三次返回相同的工具调用（Doom Loop），系统会强制触发以打破循环","当用户在终端手动输入 /compact 命令时，系统会暂停当前任务并触发"],correct:1,explanation:"Mid-turn 压缩并不是单轮生成长了就压，而是必须同时满足 Token 爆了（token_limit_reached）且任务还需要继续（needs_follow_up），才会触发压缩以保证后续流程能走下去。"},{question:"在 Codex 的压缩管线中，纯文本截断（如 trim_function_call_history）主要扮演什么角色？",options:["作为首选的压缩手段，以避免调用 LLM 生成摘要带来的昂贵 API 成本","作为保障 Compact 请求本身能够成功发送给 LLM 的工程兜底机制","作为专门用于处理图片和多模态二进制数据的预处理步骤","作为在 TUI 界面上渲染对话历史时的显示截断逻辑，不影响发给模型的数据"],correct:1,explanation:"Codex 的核心压缩产物依赖 LLM。纯文本截断（如裁剪冗长的工具输出或移除最早的消息）主要是在历史太长导致压缩请求本身都发不出去时，作为兜底机制使用。"},{question:"在 Remote v2 的 build_v2_compacted_history 中，压缩后的历史结构是如何组装的？",options:["先将 LLM 生成的摘要节点放在最前面，然后再追加最近 N 轮的原始消息","完全丢弃所有原始消息，只保留一个包含了全局摘要的 System Prompt","先保留部分原始消息（按预算截断），然后再把 Compaction 节点（摘要）放在最后","将摘要节点与原始消息交替穿插，以保持对话的时间线顺序"],correct:2,explanation:"在 Remote v2 的实现中，系统会先保留部分原始消息（retained_messages），然后再把 LLM 生成的 Compaction 节点追加到末尾，这与 Local 压缩的结构有所不同。"},{question:"对比 Claude Code 的 5 级降级策略，Codex 在压缩策略上的核心差异是什么？",options:["Codex 追求“成本优先”，尽量使用纯数据结构操作来避免昂贵的 LLM 调用","Codex 的核心压缩产物依赖 LLM 语义摘要，而 Claude Code 前 4 级全是纯数据结构操作","Codex 采用多线程并发压缩技术，将压缩延迟降到最低，而 Claude Code 是单线程","Codex 在压缩前会强制进行敏感词过滤和沙箱权限检查，而 Claude Code 不会"],correct:1,explanation:"Claude Code 倾向于纯文本截断和折叠（成本优先），直到最后才调 LLM；而 Codex 的三种实现（Local, Remote v1, v2）的核心产物都是 LLM 摘要，侧重逻辑连贯性。"}];return(d,s)=>{const a=e("Quiz");return n(),t("div",null,[s[0]||(s[0]=l("",47)),p(a,{questions:i})])}}});export{E as __pageData,g as default};
